/// Finds the maximum value in a vector of integers.
///
/// Args:
///     numbers: A slice of i32 integers.
///
/// Returns:
///     Some(i32) if the vector is not empty, containing the maximum value.
///     None if the vector is empty.
fn find_max(numbers: &[i32]) -> Option<i32> {
    if numbers.is_empty() {
        return None;
    }

    let mut max_value = numbers[0];

    for &number in numbers {
        if number > max_value {
            max_value = number;
        }
    }

    Some(max_value)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_vector() {
        assert_eq!(find_max(&[]), None);
    }

    #[test]
    fn test_single_element_vector() {
        assert_eq!(find_max(&[5]), Some(5));
    }

    #[test]
    fn test_positive_numbers() {
        assert_eq!(find_max(&[1, 5, 2, 8, 3]), Some(8));
    }

    #[test]
    fn test_negative_numbers() {
        assert_eq!(find_max(&[-1, -5, -2, -8, -3]), Some(-1));
    }

    #[test]
    fn test_mixed_numbers() {
        assert_eq!(find_max(&[-1, 5, -2, 8, -3]), Some(8));
    }
}
```

